const build = ([id, name, kind, price, mrp, gallery]) => {
  const pool = BLURB[kind] || BLURB.shirt;
  const seed = name.length + id.length;
  return {
    id,
    name,
    slug: id,
    brand: 'MUFTI',
    price,
    mrp,
    tagline: TAGLINE[kind] || TAGLINE.shirt,
    description: pool[seed % pool.length],
    highlights: SPECS[kind] || SPECS.shirt,
    image: `/images/mufti/${gallery[0]}`,
    images: gallery.map((f) => `/images/mufti/${f}`),
  };
};

